/**
 * Offline receive auditor.  The wire codec in this project is packet-local, but the
 * audit contract also requires a transactional receive state machine.  Keeping the
 * parser and the state transitions here makes the ordering rules (and rollback)
 * explicit and avoids hidden state in the DTO adapters.
 */
public final class ReceiveAudit {
    static final long MAX_PN = (1L << 62) - 1;
    static final long MAX_COUNT = 1L << 60;
    static final int I = 0, H = 1, A = 2;
    static final String[] LEVEL_NAME = {"I", "H", "A"};
    static final byte[] VERSION = {0, 0, 0, 1};
    static final byte[] EMPTY = new byte[0];

    public Map<String,Object> audit(Main.Trace trace) {
        return new TraceAudit(trace).run();
    }

    // ---------------------------------------------------------------------
    // Small utilities
    // ---------------------------------------------------------------------
    static final class ByteBuf {
        byte[] a = new byte[64];
        int n;
        void ensure(int extra) {
            if (n + extra <= a.length) return;
            int cap = a.length;
            while (cap < n + extra) cap = cap < 1024 ? cap * 2 : cap + (cap >> 1);
            a = Arrays.copyOf(a, cap);
        }
        void write(int b) { ensure(1); a[n++] = (byte)b; }
        void write(byte[] b) { ensure(b.length); System.arraycopy(b, 0, a, n, b.length); n += b.length; }
        void write(byte[] b, int off, int len) { ensure(len); System.arraycopy(b, off, a, n, len); n += len; }
        byte[] bytes() { return Arrays.copyOf(a, n); }
        int size() { return n; }
    }

    static final class Varint {
        final long value; final int width; final int next;
        Varint(long v, int w, int p) { value = v; width = w; next = p; }
    }

    /** Null means that the varint is truncated.  Overlong encodings are accepted here. */
    static Varint tryVarint(byte[] b, int pos) {
        if (pos < 0 || pos >= b.length) return null;
        int first = b[pos] & 255;
        int width = 1 << (first >>> 6);
        if (pos + width > b.length) return null;
        long v = first & 0x3f;
        for (int i = 1; i < width; i++) v = (v << 8) | (b[pos + i] & 255L);
        return new Varint(v, width, pos + width);
    }

    static int minVarintWidth(long v) {
        if (v <= 63L) return 1;
        if (v <= 16383L) return 2;
        if (v <= 1073741823L) return 4;
        return 8;
    }

    static void writeVarint(ByteBuf out, long v) {
        int w = minVarintWidth(v);
        if (w == 1) {
            out.write((int)v);
        } else if (w == 2) {
            out.write((int)(0x40 | (v >>> 8)));
            out.write((int)v);
        } else if (w == 4) {
            out.write((int)(0x80 | (v >>> 24)));
            out.write((int)(v >>> 16));
            out.write((int)(v >>> 8));
            out.write((int)v);
        } else {
            out.write((int)(0xc0 | (v >>> 56)));
            for (int s = 48; s >= 0; s -= 8) out.write((int)(v >>> s));
        }
    }

    static String shaHex(byte[] data) {
        try {
            return Main.hex(MessageDigest.getInstance("SHA-256").digest(data));
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static String shaHexIntervalList(List<long[]> ranges) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            byte[] word = new byte[8];
            for (long[] r : ranges) {
                putLongBE(word, 0, r[0]); md.update(word);
                putLongBE(word, 0, r[1]); md.update(word);
            }
            return Main.hex(md.digest());
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    static void putLongBE(byte[] b, int off, long v) {
        for (int i = 7; i >= 0; i--) { b[off + i] = (byte)v; v >>>= 8; }
    }

    static Map<String,Object> obj(Object... kv) {
        Map<String,Object> m = new LinkedHashMap<>();
        for (int i = 0; i < kv.length; i += 2) m.put((String)kv[i], kv[i+1]);
        return m;
    }

    static List<Object> lng(long... vals) {
        List<Object> r = new ArrayList<>(vals.length);
        for (long v : vals) r.add(v);
        return r;
    }

    static boolean bytesEqual(byte[] a, byte[] b) {
        return Arrays.equals(a, b);
    }

    static final class ByteKey {
        final byte[] b; final int h;
        ByteKey(byte[] x) { b = x.clone(); h = Arrays.hashCode(b); }
        @Override public int hashCode() { return h; }
        @Override public boolean equals(Object o) {
            return o instanceof ByteKey && Arrays.equals(b, ((ByteKey)o).b);
        }
    }

    static final class BadHeader extends Exception {
        BadHeader() { super(null, null, false, false); }
    }

    static final class FrameFailure extends Exception {
        final String status; final int offset;
        FrameFailure(String s, int o) { super(null, null, false, false); status = s; offset = o; }
    }

    // ---------------------------------------------------------------------
    // Header representation / parsing
    // ---------------------------------------------------------------------
    static final class Header {
        int level;
        int offset;
        int nextPos;               // ignored for short headers
        int pnWidth;
        long rawPn;
        byte[] destination = EMPTY;
        byte[] source = EMPTY;
        byte[] token = EMPTY;
        byte[] payload = EMPTY;
        int phase;                 // application key phase bit
    }

    static Header parseHeader(byte[] wire, int start, int localCidWidth) throws BadHeader {
        if (start >= wire.length) throw new BadHeader();
        int first = wire[start] & 255;
        Header h = new Header();
        h.offset = start;
        h.pnWidth = (first & 3) + 1;

        if ((first & 0x80) != 0) {
            // Long header.  Exactly the two supported long types and flags are legal.
            if (first >= 0xc0 && first <= 0xc3) h.level = I;
            else if (first >= 0xe0 && first <= 0xe3) h.level = H;
            else throw new BadHeader();

            int p = start + 1;
            if (p + 4 > wire.length) throw new BadHeader();
            for (int i = 0; i < 4; i++) if (wire[p + i] != VERSION[i]) throw new BadHeader();
            p += 4;

            if (p >= wire.length) throw new BadHeader();
            int dcidLen = wire[p++] & 255;
            if (dcidLen > 20 || p + dcidLen > wire.length) throw new BadHeader();
            h.destination = Arrays.copyOfRange(wire, p, p + dcidLen);
            p += dcidLen;

            if (p >= wire.length) throw new BadHeader();
            int scidLen = wire[p++] & 255;
            if (scidLen > 20 || p + scidLen > wire.length) throw new BadHeader();
            h.source = Arrays.copyOfRange(wire, p, p + scidLen);
            p += scidLen;

            if (h.level == I) {
                Varint tv = tryVarint(wire, p);
                if (tv == null) throw new BadHeader();
                long tokenLen = tv.value;
                p = tv.next;
                if (tokenLen > (long)(wire.length - p)) throw new BadHeader();
                h.token = Arrays.copyOfRange(wire, p, p + (int)tokenLen);
                p += (int)tokenLen;
            }

            Varint lv = tryVarint(wire, p);
            if (lv == null) throw new BadHeader();
            long length = lv.value;
            p = lv.next;
            if (length < h.pnWidth) throw new BadHeader();
            if (length > (long)(wire.length - p)) throw new BadHeader();

            int packetEnd = p + (int)length;
            long raw = 0;
            for (int i = 0; i < h.pnWidth; i++) raw = (raw << 8) | (wire[p + i] & 255L);
            h.rawPn = raw;
            int payloadStart = p + h.pnWidth;
            h.payload = Arrays.copyOfRange(wire, payloadStart, packetEnd);
            h.nextPos = packetEnd;
            return h;
        }

        // Short header: terminal and fixed-width DCID.
        if ((first & 0x40) == 0 || (first & 0x18) != 0) throw new BadHeader();
        h.level = A;
        h.phase = (first >>> 2) & 1;
        int p = start + 1;
        if (p + localCidWidth + h.pnWidth > wire.length) throw new BadHeader();
        h.destination = Arrays.copyOfRange(wire, p, p + localCidWidth);
        p += localCidWidth;
        long raw = 0;
        for (int i = 0; i < h.pnWidth; i++) raw = (raw << 8) | (wire[p + i] & 255L);
        h.rawPn = raw;
        p += h.pnWidth;
        h.payload = Arrays.copyOfRange(wire, p, wire.length);
        h.nextPos = wire.length;
        return h;
    }

    static long reconstructPn(long expected, int width, long raw) {
        long mod = 1L << (8 * width);
        long base = (expected / mod) * mod + raw;
        long best = -1, bestDist = Long.MAX_VALUE;
        long[] candidates = {base - mod, base, base + mod};
        for (long c : candidates) {
            if (c < 0) continue;
            long d = c >= expected ? c - expected : expected - c;
            if (d < bestDist || (d == bestDist && (best < 0 || c > best))) {
                best = c; bestDist = d;
            }
        }
        return best < 0 ? 0 : best;
    }

    // ---------------------------------------------------------------------
    // Byte storage and interval sets
    // ---------------------------------------------------------------------
    static final class ByteInsertion {
        final ByteStore store; final long key;
        ByteInsertion(ByteStore s, long k) { store = s; key = k; }
    }

    static final class ByteStore {
        // Physical pieces never overlap.  Adjacent pieces are deliberately not merged
        // so that a packet-level undo is just the removal of the pieces it inserted.
        final TreeMap<Long,byte[]> pieces = new TreeMap<>();

        void insert(long off, byte[] data, PacketTxn tx) throws FrameFailure {
            if (data.length == 0) return;
            long end = off + data.length; // caller checked <= MAX_PN

            // First validate all intersections.  No mutation occurs on a conflict.
            Map.Entry<Long,byte[]> e = pieces.floorEntry(off);
            if (e == null || e.getKey() + e.getValue().length <= off) e = pieces.ceilingEntry(off);
            while (e != null && e.getKey() < end) {
                long s = e.getKey();
                long se = s + e.getValue().length;
                long os = Math.max(s, off), oe = Math.min(se, end);
                byte[] old = e.getValue();
                for (long at = os; at < oe; at++) {
                    if (old[(int)(at - s)] != data[(int)(at - off)])
                        throw new FrameFailure("PROTOCOL_VIOLATION", 0); // caller replaces offset
                }
                e = pieces.higherEntry(s);
            }

            // Insert only the uncovered gaps.
            long cur = off;
            Map.Entry<Long,byte[]> floor = pieces.floorEntry(cur);
            if (floor != null && floor.getKey() + floor.getValue().length > cur)
                cur = floor.getKey() + floor.getValue().length;

            while (cur < end) {
                Map.Entry<Long,byte[]> next = pieces.ceilingEntry(cur);
                if (next != null && next.getKey() == cur) {
                    cur += next.getValue().length;
                    continue;
                }
                long gapEnd = next == null ? end : Math.min(end, next.getKey());
                if (gapEnd > cur) {
                    byte[] piece = Arrays.copyOfRange(data, (int)(cur - off), (int)(gapEnd - off));
                    pieces.put(cur, piece);
                    if (tx != null) tx.byteAdds.add(new ByteInsertion(this, cur));
                    cur = gapEnd;
                }
            }
        }

        List<long[]> logicalRanges() {
            List<long[]> r = new ArrayList<>();
            long s = -1, e = -1;
            for (Map.Entry<Long,byte[]> x : pieces.entrySet()) {
                long ns = x.getKey(), ne = ns + x.getValue().length;
                if (s < 0) { s = ns; e = ne; }
                else if (ns <= e) { if (ne > e) e = ne; }
                else { r.add(new long[]{s, e}); s = ns; e = ne; }
            }
            if (s >= 0) r.add(new long[]{s, e});
            return r;
        }

        long unique() {
            long n = 0;
            for (long[] r : logicalRanges()) n += r[1] - r[0];
            return n;
        }

        long prefix() {
            List<long[]> r = logicalRanges();
            if (r.isEmpty() || r.get(0)[0] != 0) return 0;
            return r.get(0)[1];
        }

        byte[] prefixBytes(long prefix) {
            if (prefix <= 0) return EMPTY;
            ByteBuf b = new ByteBuf();
            for (Map.Entry<Long,byte[]> x : pieces.entrySet()) {
                long s = x.getKey();
                if (s >= prefix) break;
                long e = s + x.getValue().length;
                if (e <= 0) continue;
                int from = (int)Math.max(0, -s);
                int to = (int)Math.min(x.getValue().length, prefix - s);
                if (to > from) b.write(x.getValue(), from, to - from);
            }
            return b.bytes();
        }
    }

    static final class StreamState {
        final long id;
        long high, sendMax;
        Long finalSize, reset, stop;
        final ByteStore bytes = new ByteStore();
        StreamState(long id) { this.id = id; }
    }

    static final class StreamUndo {
        long high, sendMax;
        Long finalSize, reset, stop;
        StreamUndo(StreamState s) {
            high = s.high; sendMax = s.sendMax;
            finalSize = s.finalSize; reset = s.reset; stop = s.stop;
        }
        void restore(StreamState s) {
            s.high = high; s.sendMax = sendMax;
            s.finalSize = finalSize; s.reset = reset; s.stop = stop;
        }
    }

    static final class AckState {
        // Half-open, sorted, disjoint and adjacent-merged.
        List<long[]> ranges = new ArrayList<>();
        final long[] ecn = {0, 0, 0};
    }

    static final class EpochStats {
        long min, max, count;
        EpochStats(long p) { min = max = p; count = 1; }
    }

    static final class CidRecord {
        final long sequence;
        final byte[] cid, token;
        CidRecord(long s, byte[] c, byte[] t) { sequence = s; cid = c.clone(); token = t.clone(); }
    }

    static final class PeerCidState {
        long threshold = 0;
        final TreeMap<Long,CidRecord> bySeq = new TreeMap<>();
        final HashMap<ByteKey,Long> byCid = new HashMap<>();
        final TreeSet<Long> active = new TreeSet<>();
    }

    static final class PeerCidUndo {
        boolean started;
        long oldThreshold;
        final List<Long> observed = new ArrayList<>();
        // op 1 = active.add, op 2 = active.remove; replayed in reverse.
        final List<long[]> activeOps = new ArrayList<>();
    }

    static final class ClosedInfo {
        final int event, packet, offset; final String code;
        ClosedInfo(int e, int p, int o, String c) { event = e; packet = p; offset = o; code = c; }
    }

    static final class FrameResult {
        final byte[] payload; final boolean closed; final int closeOffset;
        FrameResult(byte[] p, boolean c, int o) { payload = p; closed = c; closeOffset = o; }
    }

    static final class PacketOutcome {
        int level; long pn; Long epoch; String status; byte[] canonical;
        boolean accepted;
    }

    static final class DatagramResult {
        Map<String,Object> row;
        List<Map<String,Object>> packets;
    }

    // ---------------------------------------------------------------------
    // Per-packet transaction
    // ---------------------------------------------------------------------
    final class PacketTxn {
        final TraceAudit st;
        long openedBidi, openedUni, used;
        long sendMaxData, sendBidi, sendUni;

        final Map<Long,StreamUndo> streamUndos = new HashMap<>();
        final Set<Long> createdStreams = new HashSet<>();
        final List<ByteInsertion> byteAdds = new ArrayList<>();

        final List<long[]>[] ackNew = new List[3];
        final long[][] ackEcnNew = new long[3][];

        PeerCidUndo peerUndo;
        final Set<Long> localRetireNew = new HashSet<>();

        @SuppressWarnings("unchecked")
        PacketTxn(TraceAudit st) {
            this.st = st;
            openedBidi = st.openedBidi; openedUni = st.openedUni; used = st.used;
            sendMaxData = st.sendMaxData; sendBidi = st.sendMaxStreams[0]; sendUni = st.sendMaxStreams[1];
            for (int i = 0; i < 3; i++) ackNew[i] = null;
        }

        StreamState getStream(long id) {
            StreamState s = st.streams.get(id);
            if (s == null) {
                s = new StreamState(id);
                st.streams.put(id, s);
                createdStreams.add(id);
            } else if (!createdStreams.contains(id) && !streamUndos.containsKey(id)) {
                streamUndos.put(id, new StreamUndo(s));
            }
            return s;
        }

        void addAck(int level, List<long[]> ranges, long[] ecn) {
            if (ranges != null && !ranges.isEmpty()) {
                if (ackNew[level] == null) ackNew[level] = new ArrayList<>();
                ackNew[level].addAll(ranges);
            }
            if (ecn != null) {
                if (ackEcnNew[level] == null) ackEcnNew[level] = new long[]{0,0,0};
                for (int i = 0; i < 3; i++) if (ecn[i] > ackEcnNew[level][i]) ackEcnNew[level][i] = ecn[i];
            }
        }

        void rollback() {
            for (int i = byteAdds.size() - 1; i >= 0; i--) {
                ByteInsertion x = byteAdds.get(i);
                x.store.pieces.remove(x.key);
            }
            for (Map.Entry<Long,StreamUndo> e : streamUndos.entrySet()) {
                StreamState s = st.streams.get(e.getKey());
                if (s != null) e.getValue().restore(s);
            }
            for (Long id : createdStreams) st.streams.remove(id);

            st.openedBidi = openedBidi; st.openedUni = openedUni; st.used = used;
            st.sendMaxData = sendMaxData; st.sendMaxStreams[0] = sendBidi; st.sendMaxStreams[1] = sendUni;

            if (peerUndo != null && peerUndo.started) {
                for (int i = peerUndo.activeOps.size() - 1; i >= 0; i--) {
                    long[] op = peerUndo.activeOps.get(i);
                    if (op[0] == 1) st.peerCids.active.remove(op[1]);
                    else st.peerCids.active.add(op[1]);
                }
                for (Long seq : peerUndo.observed) {
                    CidRecord rec = st.peerCids.bySeq.remove(seq);
                    if (rec != null) st.peerCids.byCid.remove(new ByteKey(rec.cid));
                }
                st.peerCids.threshold = peerUndo.oldThreshold;
            }
            // ACK and local-retirement additions were staged, so discarding them is enough.
        }

        void commitAckAndRetire() {
            for (int l = 0; l < 3; l++) {
                if (ackNew[l] != null) st.ack[l].ranges = unionAck(st.ack[l].ranges, ackNew[l]);
                if (ackEcnNew[l] != null) {
                    for (int i = 0; i < 3; i++)
                        if (ackEcnNew[l][i] > st.ack[l].ecn[i]) st.ack[l].ecn[i] = ackEcnNew[l][i];
                }
            }
            st.retiredLocal.addAll(localRetireNew);
        }
    }

    // ---------------------------------------------------------------------
    // Trace state and audit engine
    // ---------------------------------------------------------------------
    final class TraceAudit {
        final Main.Trace trace;
        final long connLimit, streamLimit, bidiLimit, uniLimit;
        final int cidLimit;
        final List<byte[]> localCids;
        final int localCidWidth;
        final Map<ByteKey,Integer> localCidSeq = new HashMap<>();
        final long localBidiLimit, localUniLimit;

        final boolean[] keys = new boolean[3];
        final Set<Long>[] seen = new HashSet[3];
        final long[] receivedLargest = {-1, -1, -1};
        final TreeMap<Long,EpochStats> epochs = new TreeMap<>();
        long keyEpoch = 0;

        long openedBidi = 0, openedUni = 0;
        long used = 0, sendMaxData = 0;
        final long[] sendMaxStreams = {0, 0};

        final TreeMap<Long,StreamState> streams = new TreeMap<>();
        final ByteStore[] crypto = {new ByteStore(), new ByteStore(), new ByteStore()};
        final AckState[] ack = {new AckState(), new AckState(), new AckState()};
        final PeerCidState peerCids = new PeerCidState();
        final Set<Integer> retiredLocal = new TreeSet<>();
        ClosedInfo closed;

        final List<Map<String,Object>> packetRows = new ArrayList<>();
        final List<Map<String,Object>> datagramRows = new ArrayList<>();

        @SuppressWarnings("unchecked")
        TraceAudit(Main.Trace t) {
            trace = t;
            connLimit = t.connection; streamLimit = t.stream;
            bidiLimit = t.bidi; uniLimit = t.uni; cidLimit = t.cidLimit;
            localBidiLimit = t.localBidi; localUniLimit = t.localUni;
            localCids = t.localCids;
            localCidWidth = localCids.get(0).length;
            for (int i = 0; i < localCids.size(); i++) localCidSeq.put(new ByteKey(localCids.get(i)), i);
            for (int i = 0; i < 3; i++) {
                seen[i] = new HashSet<>();
                if (t.received[i] >= 0) {
                    receivedLargest[i] = t.received[i];
                    seen[i].add(t.received[i]);
                }
            }
            if (t.received[A] >= 0) epochs.put(0L, new EpochStats(t.received[A]));
            keys[I] = true; keys[H] = false; keys[A] = false;

            peerCids.bySeq.put(0L, new CidRecord(0L, t.peerCid, t.peerToken));
            peerCids.byCid.put(new ByteKey(t.peerCid), 0L);
            peerCids.active.add(0L);
        }

        Map<String,Object> run() {
            for (int ei = 0; ei < trace.events.size(); ei++) {
                Main.Event ev = trace.events.get(ei);
                if (ev.keys != null) {
                    if (closed == null) {
                        keys[I] = keys[H] = keys[A] = false;
                        for (String k : ev.keys) {
                            if ("I".equals(k)) keys[I] = true;
                            else if ("H".equals(k)) keys[H] = true;
                            else if ("A".equals(k)) keys[A] = true;
                        }
                    }
                } else {
                    DatagramResult dr = processDatagram(ei, ev);
                    packetRows.addAll(dr.packets);
                    datagramRows.add(dr.row);
                }
            }
            return result();
        }

        DatagramResult processDatagram(int event, Main.Event ev) {
            List<Map<String,Object>> rows = new ArrayList<>();
            MessageDigest dg;
            try { dg = MessageDigest.getInstance("SHA-256"); }
            catch (Exception e) { throw new RuntimeException(e); }

            int attempt = 0, pos = 0;
            long accepted = 0, bytes = 0;
            byte[] wire = ev.wire == null ? EMPTY : ev.wire;

            while (pos < wire.length) {
                Header h;
                try {
                    h = parseHeader(wire, pos, localCidWidth);
                } catch (BadHeader bh) {
                    rows.add(packetRow(event, attempt, pos, null, null, null, "BAD_HEADER", null));
                    attempt++;
                    break; // BAD_HEADER abandons this datagram remainder
                }

                long expected = receivedLargest[h.level] < 0 ? 0 : receivedLargest[h.level] + 1;
                long pn = reconstructPn(expected, h.pnWidth, h.rawPn);
                PacketOutcome out = processPacket(event, attempt, h, pn, expected, ev.auth);
                rows.add(packetRow(event, attempt, pos, h.level, pn, out.epoch, out.status,
                        out.accepted ? shaHex(out.canonical) : null));
                if (out.accepted) {
                    accepted++;
                    bytes += out.canonical.length;
                    dg.update(out.canonical);
                }
                attempt++;

                if (h.level == A) break;
                pos = h.nextPos;
            }

            Map<String,Object> row = obj(
                    "event", event,
                    "packets", (long)rows.size(),
                    "accepted", accepted,
                    "bytes", bytes,
                    "sha256", Main.hex(dg.digest()));
            DatagramResult dr = new DatagramResult();
            dr.row = row; dr.packets = rows;
            return dr;
        }

        Map<String,Object> packetRow(int event, int packet, int offset, Integer level,
                                     Long pn, Long epoch, String status, String sha) {
            return obj("event", event, "packet", packet, "offset", offset,
                    "level", level == null ? null : LEVEL_NAME[level],
                    "pn", pn, "epoch", epoch, "status", status, "sha256", sha);
        }

        boolean authAllowedA(long gen, int phase) {
            if (gen < 0) return false;
            boolean window = gen == keyEpoch
                    || (keyEpoch > 0 && gen == keyEpoch - 1)
                    || (keyEpoch < MAX_PN && gen == keyEpoch + 1);
            if (!window) return false;
            return (gen & 1L) == (long)phase;
        }

        boolean epochOrderViolation(long gen, long pn) {
            // Every packet in a higher epoch must be strictly larger than every packet
            // in a lower epoch.  This packet is the only new member of gen.
            for (Map.Entry<Long,EpochStats> e : epochs.entrySet()) {
                long ep = e.getKey(); EpochStats s = e.getValue();
                if (s.count == 0) continue;
                if (ep < gen) {
                    if (s.max >= pn) return true;
                } else if (ep > gen) {
                    if (s.min <= pn) return true;
                }
            }
            return false;
        }

        PacketOutcome processPacket(int event, int packet, Header h, long pn,
                                    long expectedBefore, List<Long> authList) {
            PacketOutcome out = new PacketOutcome();
            out.level = h.level; out.pn = pn; out.epoch = null;

            if (closed != null) { out.status = "CLOSED"; return out; }

            Integer destSeqObj = localCidSeq.get(new ByteKey(h.destination));
            if (destSeqObj == null || retiredLocal.contains(destSeqObj)) {
                out.status = "DROP_CID"; return out;
            }
            int destSeq = destSeqObj;

            if (!keys[h.level]) { out.status = "NO_KEY"; return out; }
            if (pn > MAX_PN) { out.status = "PN_RANGE"; return out; }

            Long auth = packet < authList.size() ? authList.get(packet) : null;
            Long annEpoch = null;
            if (h.level == A) {
                if (auth == null || !authAllowedA(auth, h.phase)) {
                    out.status = "AUTH"; return out;
                }
                annEpoch = auth;
                out.epoch = annEpoch;
            } else {
                // Initial and Handshake have generation 0 only.
                if (auth == null || auth.longValue() != 0L) {
                    out.status = "AUTH"; return out;
                }
            }

            if (seen[h.level].contains(pn)) { out.status = "DUPLICATE"; return out; }

            if (h.level == A && epochOrderViolation(annEpoch, pn)) {
                out.status = "KEY_UPDATE_ERROR";
                closed = new ClosedInfo(event, packet, 0, out.status);
                return out;
            }

            PacketTxn tx = new PacketTxn(this);
            FrameResult fr;
            try {
                fr = processFrames(h.level, h.payload, tx, destSeq);
            } catch (FrameFailure f) {
                tx.rollback();
                out.status = f.status;
                closed = new ClosedInfo(event, packet, f.offset, f.status);
                return out;
            }

            // All frame effects are now known to be successful.
            tx.commitAckAndRetire();

            // Only successful packets advance PN/epoch history.
            seen[h.level].add(pn);
            if (receivedLargest[h.level] < 0 || pn > receivedLargest[h.level])
                receivedLargest[h.level] = pn;
            if (h.level == A) {
                EpochStats es = epochs.get(annEpoch);
                if (es == null) epochs.put(annEpoch, new EpochStats(pn));
                else {
                    if (pn < es.min) es.min = pn;
                    if (pn > es.max) es.max = pn;
                    es.count++;
                }
                if (annEpoch == keyEpoch + 1 && keyEpoch < MAX_PN) keyEpoch = annEpoch;
            }

            byte[] canonical = canonicalize(h, pn, expectedBefore, fr.payload);
            out.canonical = canonical;
            out.accepted = true;
            out.status = fr.closed ? "PEER_CLOSE" : "OK";
            if (fr.closed) closed = new ClosedInfo(event, packet, fr.closeOffset, "PEER_CLOSE");
            return out;
        }

        // -----------------------------------------------------------------
        // Frame decoding, validation and canonical reconstruction
        // -----------------------------------------------------------------
        FrameResult processFrames(int level, byte[] payload, PacketTxn tx, int destSeq) throws FrameFailure {
            if (payload.length == 0) throw new FrameFailure("FRAME_ENCODING_ERROR", 0);
            ByteBuf out = new ByteBuf();
            int pos = 0;

            while (pos < payload.length) {
                int start = pos;
                Varint tv = tryVarint(payload, pos);
                if (tv == null) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                if (tv.width != minVarintWidth(tv.value))
                    throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                long type = tv.value;
                pos = tv.next;
                if (!supportedFrame(type)) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                checkFrameLevel(type, level, start);
                writeVarint(out, type);

                BodyCursor b = new BodyCursor(payload, pos, start);
                switch ((int)type) {
                    case 0x00:
                    case 0x01:
                        break;

                    case 0x02:
                    case 0x03: {
                        long largest = b.v(); writeVarint(out, largest);
                        long delay = b.v(); writeVarint(out, delay);
                        long count = b.v(); writeVarint(out, count);
                        long first = b.v(); writeVarint(out, first);
                        if (first > largest) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        if (count > (long)(payload.length - b.pos) / 2L)
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);

                        List<long[]> frameRanges = new ArrayList<>();
                        long low = largest - first;
                        frameRanges.add(new long[]{low, largest + 1});
                        for (long i = 0; i < count; i++) {
                            long gap = b.v(); writeVarint(out, gap);
                            long range = b.v(); writeVarint(out, range);
                            if (low < gap + 2L)
                                throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                            long high = low - gap - 2L;
                            if (range > high)
                                throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                            low = high - range;
                            frameRanges.add(new long[]{low, high + 1});
                        }
                        long[] ecn = null;
                        if (type == 0x03) {
                            ecn = new long[3];
                            for (int i = 0; i < 3; i++) {
                                ecn[i] = b.v();
                                writeVarint(out, ecn[i]);
                            }
                        }
                        tx.addAck(level, frameRanges, ecn);
                        break;
                    }

                    case 0x04: {
                        long id = b.v(); writeVarint(out, id);
                        long error = b.v(); writeVarint(out, error);
                        long finalSize = b.v(); writeVarint(out, finalSize);
                        StreamState s = ensureReceiveStream(id, start, tx);
                        if (finalSize < s.high)
                            throw new FrameFailure("FINAL_SIZE_ERROR", start);
                        if (s.finalSize != null && finalSize != s.finalSize.longValue())
                            throw new FrameFailure("FINAL_SIZE_ERROR", start);
                        long candidate = finalSize;
                        if (candidate > streamLimit)
                            throw new FrameFailure("FLOW_CONTROL_ERROR", start);
                        long delta = candidate - s.high;
                        if (delta > connLimit - used)
                            throw new FrameFailure("FLOW_CONTROL_ERROR", start);
                        used += delta;
                        s.high = candidate;
                        s.finalSize = finalSize;
                        if (s.reset == null) s.reset = error;
                        break;
                    }

                    case 0x05: {
                        long id = b.v(); writeVarint(out, id);
                        long error = b.v(); writeVarint(out, error);
                        StreamState s = ensureSendStream(id, start, tx);
                        if (s.stop == null) s.stop = error;
                        break;
                    }

                    case 0x06: {
                        long off = b.v(); writeVarint(out, off);
                        long len = b.v(); writeVarint(out, len);
                        if (len > (long)(payload.length - b.pos))
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        byte[] data = b.take((int)len);
                        out.write(data);
                        if (off > MAX_PN - len)
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        try {
                            crypto[level].insert(off, data, tx);
                        } catch (FrameFailure f) {
                            throw new FrameFailure("PROTOCOL_VIOLATION", start);
                        }
                        break;
                    }

                    case 0x08: case 0x09: case 0x0a: case 0x0b:
                    case 0x0c: case 0x0d: case 0x0e: case 0x0f: {
                        long id = b.v(); writeVarint(out, id);
                        boolean hasOff = (type & 4) != 0;
                        boolean hasLen = (type & 2) != 0;
                        boolean fin = (type & 1) != 0;
                        long off = hasOff ? b.v() : 0;
                        if (hasOff) writeVarint(out, off);
                        long len;
                        byte[] data;
                        if (hasLen) {
                            len = b.v(); writeVarint(out, len);
                            if (len > (long)(payload.length - b.pos))
                                throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                            data = b.take((int)len);
                            out.write(data);
                        } else {
                            len = payload.length - b.pos;
                            data = b.take((int)len);
                            out.write(data);
                        }
                        if (off > MAX_PN - len)
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        long end = off + len;

                        StreamState s = ensureReceiveStream(id, start, tx);
                        long oldHigh = s.high;
                        if (s.finalSize != null) {
                            if (end > s.finalSize.longValue())
                                throw new FrameFailure("FINAL_SIZE_ERROR", start);
                            if (fin && end != s.finalSize.longValue())
                                throw new FrameFailure("FINAL_SIZE_ERROR", start);
                        }
                        if (fin) {
                            if (end < s.high)
                                throw new FrameFailure("FINAL_SIZE_ERROR", start);
                            s.finalSize = end;
                        }
                        long candidate = Math.max(s.high, end);
                        if (candidate > streamLimit)
                            throw new FrameFailure("FLOW_CONTROL_ERROR", start);
                        long delta = candidate - oldHigh;
                        if (delta > connLimit - used)
                            throw new FrameFailure("FLOW_CONTROL_ERROR", start);
                        s.high = candidate;
                        used += delta;

                        if (s.reset == null) {
                            try {
                                s.bytes.insert(off, data, tx);
                            } catch (FrameFailure f) {
                                throw new FrameFailure("PROTOCOL_VIOLATION", start);
                            }
                        }
                        break;
                    }

                    case 0x10: {
                        long maximum = b.v(); writeVarint(out, maximum);
                        if (maximum > sendMaxData) sendMaxData = maximum;
                        break;
                    }

                    case 0x11: {
                        long id = b.v(); writeVarint(out, id);
                        long maximum = b.v(); writeVarint(out, maximum);
                        StreamState s = ensureSendStream(id, start, tx);
                        if (maximum > s.sendMax) s.sendMax = maximum;
                        break;
                    }

                    case 0x12:
                    case 0x13: {
                        long maximum = b.v(); writeVarint(out, maximum);
                        if (maximum > MAX_COUNT)
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        int dir = type == 0x12 ? 0 : 1;
                        if (maximum > sendMaxStreams[dir]) sendMaxStreams[dir] = maximum;
                        break;
                    }

                    case 0x14: {
                        long limit = b.v(); writeVarint(out, limit);
                        break;
                    }

                    case 0x15: {
                        long id = b.v(); writeVarint(out, id);
                        long limit = b.v(); writeVarint(out, limit);
                        ensureReceiveStream(id, start, tx);
                        break;
                    }

                    case 0x16:
                    case 0x17: {
                        long maximum = b.v(); writeVarint(out, maximum);
                        if (maximum > MAX_COUNT)
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        break;
                    }

                    case 0x18: {
                        long sequence = b.v(); writeVarint(out, sequence);
                        long retirePrior = b.v(); writeVarint(out, retirePrior);
                        int cidLen = b.raw();
                        out.write(cidLen);
                        if (cidLen < 1 || cidLen > 20)
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        byte[] cid = b.take(cidLen); out.write(cid);
                        byte[] token = b.take(16); out.write(token);
                        if (retirePrior > sequence)
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        applyNewConnectionId(sequence, retirePrior, cid, token, tx, start);
                        break;
                    }

                    case 0x19: {
                        long sequence = b.v(); writeVarint(out, sequence);
                        if (sequence < 0 || sequence >= localCids.size())
                            throw new FrameFailure("PROTOCOL_VIOLATION", start);
                        if (sequence == destSeq)
                            throw new FrameFailure("PROTOCOL_VIOLATION", start);
                        tx.localRetireNew.add(sequence);
                        break;
                    }

                    case 0x1a:
                    case 0x1b: {
                        byte[] opaque = b.take(8); out.write(opaque);
                        break;
                    }

                    case 0x1c: {
                        long error = b.v(); writeVarint(out, error);
                        long trigger = b.v(); writeVarint(out, trigger);
                        long reasonLen = b.v(); writeVarint(out, reasonLen);
                        if (reasonLen > (long)(payload.length - b.pos))
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        byte[] reason = b.take((int)reasonLen); out.write(reason);
                        return new FrameResult(out.bytes(), true, start);
                    }

                    case 0x1d: {
                        long error = b.v(); writeVarint(out, error);
                        long reasonLen = b.v(); writeVarint(out, reasonLen);
                        if (reasonLen > (long)(payload.length - b.pos))
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        byte[] reason = b.take((int)reasonLen); out.write(reason);
                        return new FrameResult(out.bytes(), true, start);
                    }

                    case 0x30: {
                        out.write(payload, b.pos, payload.length - b.pos);
                        b.pos = payload.length;
                        break;
                    }

                    case 0x31: {
                        long len = b.v(); writeVarint(out, len);
                        if (len > (long)(payload.length - b.pos))
                            throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                        byte[] data = b.take((int)len); out.write(data);
                        break;
                    }

                    default:
                        throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                }
                pos = b.pos;
            }
            return new FrameResult(out.bytes(), false, -1);
        }

        final class BodyCursor {
            final byte[] d; int pos; final int start;
            BodyCursor(byte[] data, int at, int frameStart) { d = data; pos = at; start = frameStart; }
            long v() throws FrameFailure {
                Varint x = tryVarint(d, pos);
                if (x == null) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                pos = x.next; return x.value;
            }
            int raw() throws FrameFailure {
                if (pos >= d.length) throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                return d[pos++] & 255;
            }
            byte[] take(int n) throws FrameFailure {
                if (n < 0 || n > d.length - pos)
                    throw new FrameFailure("FRAME_ENCODING_ERROR", start);
                byte[] r = Arrays.copyOfRange(d, pos, pos + n);
                pos += n; return r;
            }
        }

        boolean supportedFrame(long type) {
            if (type >= 0x08 && type <= 0x0f) return true;
            switch ((int)type) {
                case 0x00: case 0x01: case 0x02: case 0x03: case 0x04: case 0x05:
                case 0x06: case 0x07: case 0x10: case 0x11: case 0x12: case 0x13:
                case 0x14: case 0x15: case 0x16: case 0x17: case 0x18: case 0x19:
                case 0x1a: case 0x1b: case 0x1c: case 0x1d: case 0x1e: case 0x30:
                case 0x31:
                    return true;
                default:
                    return false;
            }
        }

        void checkFrameLevel(long type, int level, int offset) throws FrameFailure {
            // Server-only frames are a sender violation at every level.
            if (type == 0x07 || type == 0x1e)
                throw new FrameFailure("PROTOCOL_VIOLATION", offset);
            if (level != A) {
                boolean appOnly = (type >= 0x08 && type <= 0x1b)
                        || type == 0x1d || type == 0x30 || type == 0x31;
                if (appOnly) throw new FrameFailure("PROTOCOL_VIOLATION", offset);
            }
        }

        StreamState ensureReceiveStream(long id, int frameOffset, PacketTxn tx) throws FrameFailure {
            int mod = (int)(id & 3L);
            long index = id >>> 2;
            if (mod == 0) {
                if (index >= bidiLimit) throw new FrameFailure("STREAM_LIMIT_ERROR", frameOffset);
                long n = index + 1;
                if (n > openedBidi) openedBidi = n;
            } else if (mod == 2) {
                if (index >= uniLimit) throw new FrameFailure("STREAM_LIMIT_ERROR", frameOffset);
                long n = index + 1;
                if (n > openedUni) openedUni = n;
            } else if (mod == 1) {
                if (index >= localBidiLimit) throw new FrameFailure("STREAM_STATE_ERROR", frameOffset);
            } else {
                throw new FrameFailure("STREAM_STATE_ERROR", frameOffset);
            }
            return tx.getStream(id);
        }

        StreamState ensureSendStream(long id, int frameOffset, PacketTxn tx) throws FrameFailure {
            int mod = (int)(id & 3L);
            long index = id >>> 2;
            if (mod == 0) {
                if (index >= bidiLimit) throw new FrameFailure("STREAM_LIMIT_ERROR", frameOffset);
                long n = index + 1;
                if (n > openedBidi) openedBidi = n;
            } else if (mod == 1) {
                if (index >= localBidiLimit) throw new FrameFailure("STREAM_STATE_ERROR", frameOffset);
            } else if (mod == 3) {
                if (index >= localUniLimit) throw new FrameFailure("STREAM_STATE_ERROR", frameOffset);
            } else {
                throw new FrameFailure("STREAM_STATE_ERROR", frameOffset);
            }
            return tx.getStream(id);
        }

        void applyNewConnectionId(long sequence, long retirePrior, byte[] cid, byte[] token,
                                  PacketTxn tx, int frameOffset) throws FrameFailure {
            if (tx.peerUndo == null) tx.peerUndo = new PeerCidUndo();
            PeerCidUndo u = tx.peerUndo;
            if (!u.started) { u.started = true; u.oldThreshold = peerCids.threshold; }

            CidRecord existing = peerCids.bySeq.get(sequence);
            if (existing != null) {
                if (!Arrays.equals(existing.cid, cid) || !Arrays.equals(existing.token, token))
                    throw new FrameFailure("PROTOCOL_VIOLATION", frameOffset);
            } else {
                Long owner = peerCids.byCid.get(new ByteKey(cid));
                if (owner != null)
                    throw new FrameFailure("PROTOCOL_VIOLATION", frameOffset);
                CidRecord rec = new CidRecord(sequence, cid, token);
                peerCids.bySeq.put(sequence, rec);
                peerCids.byCid.put(new ByteKey(cid), sequence);
                u.observed.add(sequence);
            }

            if (retirePrior > peerCids.threshold) peerCids.threshold = retirePrior;
            long threshold = peerCids.threshold;
            while (!peerCids.active.isEmpty() && peerCids.active.first() < threshold) {
                long removed = peerCids.active.pollFirst();
                u.activeOps.add(new long[]{2, removed});
            }
            if (sequence >= threshold && peerCids.active.add(sequence))
                u.activeOps.add(new long[]{1, sequence});
            if (peerCids.active.size() > cidLimit)
                throw new FrameFailure("CONNECTION_ID_LIMIT_ERROR", frameOffset);
        }

        // -----------------------------------------------------------------
        // Canonical headers
        // -----------------------------------------------------------------
        int canonicalPnWidth(long pn, long expected) {
            for (int w = 1; w <= 4; w++) {
                long mod = 1L << (8 * w);
                long raw = pn & (mod - 1);
                if (reconstructPn(expected, w, raw) == pn) return w;
            }
            // An accepted PN necessarily had a reconstructing original width.
            return 4;
        }

        void writePn(ByteBuf out, long pn, int width) {
            for (int i = width - 1; i >= 0; i--) out.write((int)(pn >>> (8 * i)));
        }

        byte[] canonicalize(Header h, long pn, long expectedBefore, byte[] payload) {
            int width = canonicalPnWidth(pn, expectedBefore);
            ByteBuf b = new ByteBuf();
            if (h.level == A) {
                b.write(0x40 | ((h.phase & 1) << 2) | (width - 1));
                b.write(h.destination);
                writePn(b, pn, width);
                b.write(payload);
            } else {
                b.write((h.level == I ? 0xc0 : 0xe0) | (width - 1));
                b.write(VERSION);
                b.write(h.destination.length); b.write(h.destination);
                b.write(h.source.length); b.write(h.source);
                if (h.level == I) {
                    writeVarint(b, h.token.length);
                    b.write(h.token);
                }
                writeVarint(b, (long)width + payload.length);
                writePn(b, pn, width);
                b.write(payload);
            }
            return b.bytes();
        }

        // -----------------------------------------------------------------
        // Final state snapshots
        // -----------------------------------------------------------------
        List<long[]> unionAck(List<long[]> oldRanges, List<long[]> added) {
            if (added.isEmpty()) return oldRanges;
            ArrayList<long[]> all = new ArrayList<>(oldRanges.size() + added.size());
            all.addAll(oldRanges);
            all.addAll(added);
            all.sort((x, y) -> Long.compare(x[0], y[0]));
            ArrayList<long[]> merged = new ArrayList<>();
            long s = -1, e = -1;
            for (long[] r : all) {
                if (s < 0) { s = r[0]; e = r[1]; }
                else if (r[0] <= e) { if (r[1] > e) e = r[1]; }
                else { merged.add(new long[]{s, e}); s = r[0]; e = r[1]; }
            }
            if (s >= 0) merged.add(new long[]{s, e});
            return merged;
        }

        Map<String,Object> result() {
            Map<String,Object> r = obj();
            ArrayList<Object> pOut = new ArrayList<>();
            for (Map<String,Object> p : packetRows) pOut.add(p);
            r.put("packets", pOut);

            ArrayList<Object> dOut = new ArrayList<>();
            for (Map<String,Object> d : datagramRows) dOut.add(d);
            r.put("datagrams", dOut);

            if (closed == null) r.put("closed", null);
            else r.put("closed", obj("event", closed.event, "packet", closed.packet,
                    "offset", closed.offset, "code", closed.code));

            ArrayList<Object> keyOut = new ArrayList<>();
            for (int i = 0; i < 3; i++) if (keys[i]) keyOut.add(LEVEL_NAME[i]);
            r.put("keys", keyOut);

            r.put("received", obj("I", recv(A), "H", recv(H), "A", recv(A)));
            r.put("key_epoch", keyEpoch);

            ArrayList<Object> epOut = new ArrayList<>();
            for (Map.Entry<Long,EpochStats> e : epochs.entrySet()) {
                EpochStats s = e.getValue();
                if (s.count == 0) continue;
                epOut.add(obj("epoch", e.getKey(), "min", s.min, "max", s.max, "count", s.count));
            }
            r.put("epochs", epOut);

            r.put("opened", obj("bidi", openedBidi, "uni", openedUni));
            r.put("used", used);
            r.put("send_max_data", sendMaxData);
            r.put("send_max_streams", obj("bidi", sendMaxStreams[0], "uni", sendMaxStreams[1]));

            ArrayList<Object> streamOut = new ArrayList<>();
            for (StreamState s : streams.values()) {
                List<long[]> ranges = s.bytes.logicalRanges();
                long prefix = s.bytes.prefix();
                ArrayList<Object> rr = new ArrayList<>();
                for (long[] x : ranges) rr.add(lng(x[0], x[1]));
                streamOut.add(obj("id", s.id, "high", s.high, "final", s.finalSize,
                        "reset", s.reset, "stop", s.stop, "send_max", s.sendMax,
                        "ranges", rr, "unique", s.bytes.unique(), "prefix", prefix,
                        "sha256", shaHex(s.bytes.prefixBytes(prefix))));
            }
            r.put("streams", streamOut);

            ArrayList<Object> cryptoOut = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                List<long[]> ranges = crypto[i].logicalRanges();
                long prefix = crypto[i].prefix();
                ArrayList<Object> rr = new ArrayList<>();
                for (long[] x : ranges) rr.add(lng(x[0], x[1]));
                cryptoOut.add(obj("level", LEVEL_NAME[i], "ranges", rr,
                        "unique", crypto[i].unique(), "prefix", prefix,
                        "sha256", shaHex(crypto[i].prefixBytes(prefix))));
            }
            r.put("crypto", cryptoOut);

            ArrayList<Object> ackOut = new ArrayList<>();
            for (int i = 0; i < 3; i++) {
                AckState a = ack[i];
                long count = 0;
                for (long[] x : a.ranges) count += x[1] - x[0];
                long prefix = (!a.ranges.isEmpty() && a.ranges.get(0)[0] == 0)
                        ? a.ranges.get(0)[1] : 0;
                ArrayList<Object> rr = new ArrayList<>();
                for (long[] x : a.ranges) rr.add(lng(x[0], x[1]));
                ArrayList<Object> ecn = new ArrayList<>();
                for (long v : a.ecn) ecn.add(v);
                ackOut.add(obj("level", LEVEL_NAME[i], "count", count,
                        "intervals", a.ranges.size(), "prefix", prefix,
                        "sha256", shaHexIntervalList(a.ranges), "ecn", ecn));
            }
            r.put("acknowledged", ackOut);

            ArrayList<Object> peerOut = new ArrayList<>();
            for (Long seq : peerCids.active) {
                CidRecord rec = peerCids.bySeq.get(seq);
                peerOut.add(obj("sequence", seq, "id", Main.hex(rec.cid),
                        "token", Main.hex(rec.token)));
            }
            r.put("peer_cids", peerOut);
            r.put("retire_prior_to", peerCids.threshold);

            ArrayList<Object> retOut = new ArrayList<>();
            long rs = -1, re = -1;
            for (Integer q : retiredLocal) {
                long x = q;
                if (rs < 0) { rs = x; re = x + 1; }
                else if (x == re) re = x + 1;
                else { retOut.add(lng(rs, re)); rs = x; re = x + 1; }
            }
            if (rs >= 0) retOut.add(lng(rs, re));
            r.put("retired_local", retOut);

            return r;
        }

        Object recv(int level) {
            return receivedLargest[level] < 0 ? null : (Object)receivedLargest[level];
        }
    }
